def specs_i18n(sp):
    out = {'uk': [], 'ru': [], 'en': []}
    for k, v in sp.items():
        ks = k.split('|'); vs = v.split('|') if '|' in v else [v, v, v]
        for i, L in enumerate(['uk', 'ru', 'en']): out[L].append([ks[i], vs[i]])
    return out
q = lambda s: "'" + s.replace("'", "''") + "'"
print('insert into site_complexes (slug, nb_source_id, name, address, sort, i18n) values')
rows = []
for c in C:
    sp = specs_i18n(c['specs'])
    i18n = {L: {'district': c['district'][L], 'klass': c['klass'][L], 'about': c['about'][L], 'plus': c['plus'][L], 'specs': sp[L]} for L in ['uk', 'ru', 'en']}
    rows.append(f"({q(c['slug'])}, {c['nb']}, {q(c['name'])}, {q(c['address'])}, {c['sort']}, {q(json.dumps(i18n, ensure_ascii=False))}::jsonb)")
print(',\n'.join(rows))
print("on conflict (slug) do update set nb_source_id=excluded.nb_source_id, name=excluded.name, address=excluded.address, sort=excluded.sort, i18n=excluded.i18n, updated_at=now();")
